-- 2026-10-08: Cohesive orange Life and lighter goose-yellow Mineral palettes.
-- Only Theme 3 and Theme 5 are changed; original 43-token palettes archived at
-- governance/backups/loc-theme-20261008-before-four-four.json.
-- Scheme stays Light on both. Nature's independent Dark transition is untouched.
do $theme35$
declare
  n integer;
  total_dark integer;
  total_light integer;
begin
  update silver.loc_theme
  set theme_attr='{"group":"生命","scheme":"light","tokens":{"--loc-bg":"#ff8a00","--loc-panel":"#fff4e5","--loc-panel-2":"#ffdcaa","--loc-panel-strong":"rgba(255,244,229,.97)","--loc-panel-nav":"rgba(255,239,212,.97)","--loc-panel-tab":"rgba(255,220,170,.95)","--loc-rune-bg":"#fff8ef","--loc-rune-selected-bg":"#ffd08a","--loc-line":"rgba(153,79,0,.29)","--loc-line-soft":"rgba(153,79,0,.14)","--loc-line-softer":"rgba(153,79,0,.17)","--loc-line-faint":"rgba(153,79,0,.19)","--loc-text":"#512a07","--loc-muted":"#87500f","--loc-heading":"#572b00","--loc-accent":"#a45500","--loc-gold":"#965400","--loc-danger":"#9a4040","--loc-surface":"rgba(255,244,229,.96)","--loc-surface-soft":"rgba(255,152,23,.09)","--loc-surface-faint":"rgba(255,152,23,.045)","--loc-surface-status":"rgba(255,152,23,.10)","--loc-accent-surface":"rgba(255,145,5,.13)","--loc-accent-surface-strong":"rgba(255,145,5,.21)","--loc-accent-border":"rgba(164,85,0,.58)","--loc-accent-border-soft":"rgba(164,85,0,.44)","--loc-accent-border-faint":"rgba(164,85,0,.32)","--loc-gold-surface":"rgba(150,84,0,.10)","--loc-gold-surface-soft":"rgba(150,84,0,.07)","--loc-gold-border":"rgba(150,84,0,.59)","--loc-gold-border-soft":"rgba(150,84,0,.45)","--loc-gold-border-faint":"rgba(150,84,0,.34)","--loc-gold-ring":"rgba(150,84,0,.26)","--loc-gold-ring-soft":"rgba(150,84,0,.16)","--loc-danger-border":"rgba(154,64,64,.30)","--loc-primary-start":"#ffd08a","--loc-primary-end":"#ffb34d","--loc-body-glow":"#ffcb78","--loc-body-mid":"#fff0d4","--loc-hero-start":"rgba(255,206,130,.97)","--loc-hero-end":"rgba(255,244,229,.98)","--loc-shadow":"0 20px 55px rgba(153,79,0,.15)","--loc-shadow-card":"0 12px 35px rgba(153,79,0,.10)"},"style_key":"life","identity_color":"#ff8a00"}'::jsonb
  where theme_id='theme-3' and theme_name='生命'
    and theme_order=3
    and theme_attr='{"group":"生命","scheme":"light","tokens":{"--loc-bg":"#ff8a00","--loc-gold":"#a14300","--loc-line":"rgba(122,63,14,.30)","--loc-text":"#4a2508","--loc-muted":"#8a5a2b","--loc-panel":"#fff1dc","--loc-accent":"#9b4300","--loc-danger":"#9a4040","--loc-shadow":"0 20px 55px rgba(122,63,14,.16)","--loc-heading":"#6b2e00","--loc-panel-2":"#ffd39a","--loc-rune-bg":"#fff6e8","--loc-surface":"rgba(255,241,220,.92)","--loc-body-mid":"#fff0dc","--loc-hero-end":"rgba(255,249,241,.98)","--loc-body-glow":"#ffd5a6","--loc-gold-ring":"rgba(161,67,0,.25)","--loc-line-soft":"rgba(122,63,14,.15)","--loc-panel-nav":"rgba(255,232,194,.97)","--loc-panel-tab":"rgba(255,211,154,.95)","--loc-hero-start":"rgba(255,216,168,.97)","--loc-line-faint":"rgba(122,63,14,.19)","--loc-gold-border":"rgba(161,67,0,.58)","--loc-line-softer":"rgba(122,63,14,.17)","--loc-primary-end":"#e39332","--loc-shadow-card":"0 12px 35px rgba(122,63,14,.10)","--loc-gold-surface":"rgba(161,67,0,.10)","--loc-panel-strong":"rgba(255,241,220,.96)","--loc-surface-soft":"rgba(155,67,0,.055)","--loc-accent-border":"rgba(155,67,0,.58)","--loc-danger-border":"rgba(154,64,64,.30)","--loc-primary-start":"#f1b15f","--loc-surface-faint":"rgba(155,67,0,.03)","--loc-accent-surface":"rgba(155,67,0,.10)","--loc-gold-ring-soft":"rgba(161,67,0,.15)","--loc-surface-status":"rgba(155,67,0,.07)","--loc-gold-border-soft":"rgba(161,67,0,.44)","--loc-rune-selected-bg":"#ffc36c","--loc-gold-border-faint":"rgba(161,67,0,.34)","--loc-gold-surface-soft":"rgba(161,67,0,.07)","--loc-accent-border-soft":"rgba(155,67,0,.44)","--loc-accent-border-faint":"rgba(155,67,0,.34)","--loc-accent-surface-strong":"rgba(155,67,0,.18)"},"style_key":"life","identity_color":"#ff8a00"}'::jsonb;
  get diagnostics n=row_count;
  if n<>1 then raise exception 'Refusing to overwrite changed theme-3 palette'; end if;
  update silver.loc_theme
  set theme_attr='{"group":"礦物","scheme":"light","tokens":{"--loc-bg":"#fff1b2","--loc-panel":"#fffbe4","--loc-panel-2":"#ffeaa2","--loc-panel-strong":"rgba(255,251,228,.97)","--loc-panel-nav":"rgba(255,247,204,.97)","--loc-panel-tab":"rgba(255,236,168,.95)","--loc-rune-bg":"#fff9d8","--loc-rune-selected-bg":"#ffdf82","--loc-line":"rgba(123,96,16,.28)","--loc-line-soft":"rgba(123,96,16,.14)","--loc-line-softer":"rgba(123,96,16,.17)","--loc-line-faint":"rgba(123,96,16,.19)","--loc-text":"#443811","--loc-muted":"#70602a","--loc-heading":"#352b0b","--loc-accent":"#816500","--loc-gold":"#775d00","--loc-danger":"#9a4040","--loc-surface":"rgba(255,251,228,.96)","--loc-surface-soft":"rgba(222,176,40,.085)","--loc-surface-faint":"rgba(222,176,40,.045)","--loc-surface-status":"rgba(222,176,40,.10)","--loc-accent-surface":"rgba(222,176,40,.12)","--loc-accent-surface-strong":"rgba(222,176,40,.20)","--loc-accent-border":"rgba(129,101,0,.57)","--loc-accent-border-soft":"rgba(129,101,0,.43)","--loc-accent-border-faint":"rgba(129,101,0,.32)","--loc-gold-surface":"rgba(119,93,0,.10)","--loc-gold-surface-soft":"rgba(119,93,0,.07)","--loc-gold-border":"rgba(119,93,0,.60)","--loc-gold-border-soft":"rgba(119,93,0,.46)","--loc-gold-border-faint":"rgba(119,93,0,.34)","--loc-gold-ring":"rgba(119,93,0,.26)","--loc-gold-ring-soft":"rgba(119,93,0,.17)","--loc-danger-border":"rgba(154,64,64,.30)","--loc-primary-start":"#ffdf83","--loc-primary-end":"#ffce57","--loc-body-glow":"#fff1ab","--loc-body-mid":"#fff8d9","--loc-hero-start":"rgba(255,238,163,.98)","--loc-hero-end":"rgba(255,251,226,.99)","--loc-shadow":"0 20px 55px rgba(114,90,15,.12)","--loc-shadow-card":"0 12px 35px rgba(114,90,15,.08)"},"style_key":"mineral","identity_color":"#c7cdd3"}'::jsonb
  where theme_id='theme-5' and theme_name='礦物'
    and theme_order=5
    and theme_attr='{"group":"礦物","scheme":"light","tokens":{"--loc-bg":"#d9c878","--loc-gold":"#6b5715","--loc-line":"rgba(92,79,34,.30)","--loc-text":"#3e3823","--loc-muted":"#716844","--loc-panel":"#f7efc4","--loc-accent":"#75611a","--loc-danger":"#9a4040","--loc-shadow":"0 20px 55px rgba(92,79,34,.16)","--loc-heading":"#2d2818","--loc-panel-2":"#c6b45f","--loc-rune-bg":"#efe4ad","--loc-surface":"rgba(247,239,196,.92)","--loc-body-mid":"#e9dfaa","--loc-hero-end":"rgba(247,239,196,.99)","--loc-body-glow":"#d2bf69","--loc-gold-ring":"rgba(107,87,21,.28)","--loc-line-soft":"rgba(92,79,34,.15)","--loc-panel-nav":"rgba(226,211,143,.97)","--loc-panel-tab":"rgba(235,222,158,.95)","--loc-hero-start":"rgba(226,211,137,.98)","--loc-line-faint":"rgba(92,79,34,.19)","--loc-gold-border":"rgba(107,87,21,.62)","--loc-line-softer":"rgba(92,79,34,.17)","--loc-primary-end":"#bba64b","--loc-shadow-card":"0 12px 35px rgba(92,79,34,.10)","--loc-gold-surface":"rgba(107,87,21,.12)","--loc-panel-strong":"rgba(247,239,196,.96)","--loc-surface-soft":"rgba(107,87,21,.055)","--loc-accent-border":"rgba(107,87,21,.60)","--loc-danger-border":"rgba(154,64,64,.30)","--loc-primary-start":"#d8c56d","--loc-surface-faint":"rgba(107,87,21,.03)","--loc-accent-surface":"rgba(117,97,26,.12)","--loc-gold-ring-soft":"rgba(107,87,21,.17)","--loc-surface-status":"rgba(107,87,21,.07)","--loc-gold-border-soft":"rgba(107,87,21,.48)","--loc-rune-selected-bg":"#c9b45a","--loc-gold-border-faint":"rgba(107,87,21,.38)","--loc-gold-surface-soft":"rgba(107,87,21,.08)","--loc-accent-border-soft":"rgba(107,87,21,.46)","--loc-accent-border-faint":"rgba(107,87,21,.36)","--loc-accent-surface-strong":"rgba(117,97,26,.20)"},"style_key":"mineral","identity_color":"#c7cdd3"}'::jsonb;
  get diagnostics n=row_count;
  if n<>1 then raise exception 'Refusing to overwrite changed theme-5 palette'; end if;
  select count(*) filter (where theme_attr->>'scheme'='dark'),
         count(*) filter (where theme_attr->>'scheme'='light')
  into total_dark,total_light from silver.loc_theme;
  if total_dark<>4 or total_light<>4 then
    raise exception 'Expected 4 Dark / 4 Light, got % Dark / % Light',total_dark,total_light;
  end if;
  if (select count(*) from silver.loc_theme t,lateral jsonb_object_keys(t.theme_attr->'tokens') v where t.theme_id in ('theme-3','theme-5'))<>86 then
    raise exception 'Theme 3/5 must each retain 43 tokens';
  end if;
end
$theme35$;
